using System;using Mono.Cecil;using System.Linq;
class Program {static void Main(){var a=AssemblyDefinition.ReadAssembly("../../7DaysToDie_Data/Managed/Assembly-CSharp.dll");foreach(var t in a.MainModule.Types.Where(t=>new[]{"TileEntityWorkstation","XUiC_ItemStackGrid","XUiC_CraftingWindowGroup","XUiM_Recipes"}.Contains(t.Name))){Console.WriteLine("TYPE "+t.Name);foreach(var m in t.Methods.Where(m=>m.HasBody&&new[]{"read","write","SetStacks","GetSlots","get_Workstation","GetRecipes"}.Contains(m.Name))){Console.WriteLine(m.FullName);foreach(var i in m.Body.Instructions)Console.WriteLine(i);}}}}
